using System;

class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: empty env vars are now preserved (return "")
        // instead of being treated as unset (returning null).
        // Use HasEnvironmentVariable pattern to distinguish "not set" from "empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val is null && !IsEnvironmentVariableSet("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    static bool IsEnvironmentVariableSet(string variable)
    {
        return Environment.GetEnvironmentVariable(variable) is not null;
    }
}

