using System;

class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: empty env vars now return "" instead of null.
        // Previously, both "unset" and "empty" returned null on Linux.
        // Now null means truly unset; "" means explicitly set to empty.
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val is null)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
        // val == "" means explicitly set to empty — honour that as a valid value
    }
}

